procedure Doors is
   type Door_Array is array (1..100) of Boolean;
   Doors : Door_Array := (others => False);
begin
   for Pass in 1..100 loop
      for Door in 1..100 loop
         if Door mod Pass = 0 then
            Doors(Door) := not Doors(Door);
         end if;
      end loop;
   end loop;

   for I in 1..100 loop
      if Doors(I) then
         Put_Line(I'Image & " open");
      else
         Put_Line(I'Image & " closed");
      end if;
   end loop;
end Doors;

